                L2_W3_t2 = L1_B3P_out.prepare_dot3_and_assign(L1_B4P_out, L1_W4S_out, (g_cut_frac_active && cut_frac_ppa4_skip(22) && current_phase != PHASE_INIT) ? FUNC_XOR(r185, r184) : (r185), beaver3_tuples[23]);
